// =============================================================================
// Frappe Web Form Client Script: Supplier Onboarding & Registration
// DocType: Supplier Onboarding
// =============================================================================
// Features:
//   - Full GSTIN shape (incl. valid state-code prefix) & Modulo-36 Luhn-variant
//     checksum validation.
//   - Automatic PAN extraction and synchronization from a validated GSTIN,
//     kept in sync from BOTH directions (editing the GSTIN reconciles PAN,
//     and editing the PAN reconciles it against an already-valid GSTIN).
//   - PAN format verification (independent of GSTIN).
//   - Mobile number normalization to E.164, including a bare 10-digit number,
//     a leading-zero domestic-dialing prefix, or a bare (no "+") country
//     code, all treated as domestic numbers and normalized accordingly.
//   - Non-blocking toast alerts on field blur; blocking modals on submission.
//
// Fixes applied in this revision (see inline comments at each site):
//   1. Editing the PAN field after a valid GSTIN was already entered never
//      re-ran the mismatch check - the header's own "cross-reconciliation"
//      claim only held for edits made to the GSTIN field. Reconciliation is
//      now a shared helper called from both field handlers.
//   2. A GSTIN/PAN/Mobile value that was non-empty but whitespace-only (e.g.
//      a stray space) trimmed to "" for validation purposes but was left
//      sitting in the field as-is, so the field would show as "filled" while
//      being treated as "not provided". Such values are now cleared outright.
//   3. The "+91" prefix for mobile numbers was hard-coded in two separate
//      branches; pulled into CONFIG.defaultCountryCode as a single source of
//      truth, and a third branch was added for numbers typed with a bare
//      (no "+") country code, e.g. "919876543210".
//   4. The PAN-mismatch toast used indicator "yellow", which is not
//      confirmed to be a supported frappe.show_alert color in every Frappe
//      version/theme (unlike "orange", already used elsewhere here and
//      confirmed supported) - switched to "orange" for reliability. I don't
//      have visibility into whether this specific site's Frappe version
//      supports "yellow"; if it does and you'd prefer a visually distinct
//      color for mismatches vs. hard errors, it's an easy swap back.
//   5. Clicking "Submit" while a field was still focused made the browser
//      fire that field's blur handler (a non-blocking toast) an instant
//      before frappe.web_form.validate() ran for the same problem (a
//      blocking modal) - the same message appeared twice for one click.
//      showToast()/showBlockingError() are now one notify() function with
//      a short dedupe window, so an identical message repeated within ~1s
//      only displays once.
//
// Known assumptions (flagging rather than guessing silently):
//   - The GSTIN state-code whitelist (01-38, 97, 99) reflects the codes I'm
//     aware of; if GSTN has issued new codes since, entries with a newer
//     code would be wrongly rejected by shape validation. Worth a periodic
//     check against GSTN's published state-code list.
//   - Mobile normalization assumes any bare 10-digit (or 0-prefixed
//     11-digit, or bare-91-prefixed 12-digit) number is a domestic Indian
//     number and prepends "+91" accordingly. A supplier with a genuinely
//     foreign 10-digit number (no "+") would be mis-normalized. If this
//     form is only ever used for domestic suppliers this is fine as-is.
// =============================================================================

(() => {
	"use strict";

	// =========================================================================
	// 1. CONFIGURATION & CONSTANTS
	// =========================================================================
	const CONFIG = {
		// DocType / Web Form field names (customize if your DocType uses different names)
		fields: {
			gstin: "gstin",
			pan: "pan",
			mobile: "mobile"
		},

		// Default country calling code (no "+") used to normalize bare
		// domestic mobile numbers. Centralized here so it's set in one place
		// rather than hard-coded at each call site.
		defaultCountryCode: "91",

		// Validation Patterns
		patterns: {
			// Indian GSTIN: State (01-38, 97, 99) + PAN (10) + Entity (1) + 'Z' (1) + Checksum (1)
			gstin: /^(0[1-9]|[1-2]\d|3[0-8]|97|99)[A-Z]{5}\d{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/,

			// Indian PAN: 5 uppercase letters + 4 numeric digits + 1 uppercase letter
			pan: /^[A-Z]{5}\d{4}[A-Z]{1}$/,

			// E.164 International Phone Format (+ followed by 8 to 15 digits)
			mobile: /^\+[1-9]\d{7,14}$/
		},

		// Base-36 Character Set for GSTIN Checksum calculation
		gstinCharset: "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ",

		// User-facing validation messages
		messages: {
			gstinInvalidShape: "Please enter a valid 15-character GSTIN (e.g., 27AAAAA0000A1Z5).",
			gstinInvalidChecksum: "GSTIN check digit verification failed. Please check for typos.",
			panMismatch: (entered, extracted) =>
				`Note: Entered PAN (${entered}) differs from the PAN embedded in the GSTIN (${extracted}).`,
			panInvalid: "Please enter a valid 10-character PAN (e.g., AAAAA0000A).",
			mobileInvalid: "Please enter a valid mobile number with country code (e.g., +919876543210)."
		}
	};

	// =========================================================================
	// 2. UI NOTIFICATION UTILITIES
	// =========================================================================

	// Tracks the last message shown and when, so an identical message fired
	// twice in quick succession (see notify() below) only actually displays
	// once.
	let lastNotification = { message: null, time: 0 };

	// Minimum gap (ms) below which a repeat of the same message is treated
	// as a duplicate rather than a fresh, separate warning.
	const DUPLICATE_SUPPRESSION_WINDOW_MS = 1000;

	/**
	 * Shows a validation message, either as a non-blocking toast or a
	 * blocking modal, while suppressing an exact repeat of the same message
	 * shown moments earlier.
	 *
	 * This matters because clicking "Submit" while a field is still focused
	 * makes the browser fire that field's blur event (running its "on"
	 * handler below, which calls notify() with isBlocking=false) an instant
	 * before frappe.web_form.validate() runs (which calls notify() again
	 * with isBlocking=true, for the same underlying problem). Without
	 * dedupe, that one problem is reported twice - once as a toast, once as
	 * a modal - in the space of a single click.
	 *
	 * @param {string} message - Notification text.
	 * @param {Object} [options]
	 * @param {boolean} [options.isBlocking=false] - Blocking modal (submit-time) vs. non-blocking toast (field-level).
	 * @param {string} [options.indicator="orange"] - Toast color indicator (ignored for blocking modals, which are always "red").
	 */
	function notify(message, { isBlocking = false, indicator = "orange" } = {}) {
		const now = Date.now();

		if (lastNotification.message === message && now - lastNotification.time < DUPLICATE_SUPPRESSION_WINDOW_MS) {
			return;
		}

		lastNotification = { message, time: now };

		if (isBlocking) {
			frappe.msgprint({
				title: __("Validation Error"),
				indicator: "red",
				message: __(message)
			});
		} else if (typeof frappe.show_alert === "function") {
			frappe.show_alert({ message, indicator }, 6);
		} else {
			frappe.msgprint(message);
		}
	}

	// =========================================================================
	// 3. PURE VALIDATION & HELPER FUNCTIONS
	// =========================================================================

	/**
	 * Computes the expected 15th check character of a GSTIN using the
	 * official GSTN Luhn-variant Modulo-36 algorithm.
	 *
	 * Assumes `gstin` has already passed the shape regex (every character is
	 * a valid index into gstinCharset); the -1 guard below is defense in
	 * depth in case this is ever called directly on unvalidated input.
	 *
	 * @param {string} gstin - 15-character uppercase GSTIN.
	 * @returns {boolean} True if the 15th character matches the computed check digit.
	 */
	function isValidGstinChecksum(gstin) {
		let factor = 2;
		let sum = 0;

		// Traverse the first 14 characters right-to-left, alternating the
		// multiplication factor between 2 and 1 (a Luhn-style scheme).
		for (let i = gstin.length - 2; i >= 0; i--) {
			const codePoint = CONFIG.gstinCharset.indexOf(gstin[i]);
			if (codePoint === -1) return false;

			let product = factor * codePoint;
			product = Math.floor(product / 36) + (product % 36);
			sum += product;

			factor = factor === 2 ? 1 : 2;
		}

		const expectedCodePoint = (36 - (sum % 36)) % 36;
		const expectedCheckChar = CONFIG.gstinCharset[expectedCodePoint];

		return expectedCheckChar === gstin[gstin.length - 1];
	}

	/**
	 * Extracts the 10-character PAN embedded within a GSTIN (characters 3 through 12).
	 * Only meaningful once the GSTIN has passed shape + checksum validation.
	 *
	 * @param {string} gstin - Formatted 15-character GSTIN.
	 * @returns {string} 10-character PAN string.
	 */
	function extractPanFromGstin(gstin) {
		return gstin.substring(2, 12);
	}

	/**
	 * Returns the current GSTIN field value, normalized and validated
	 * (shape + checksum), or null if it's empty or currently invalid.
	 * Used to decide whether PAN-side edits have a valid GSTIN to reconcile
	 * against, without duplicating error messaging (the GSTIN field's own
	 * handler is responsible for reporting GSTIN-shaped problems).
	 *
	 * @returns {string|null}
	 */
	function getValidatedGstinOrNull() {
		const gstinValue = (frappe.web_form.get_value(CONFIG.fields.gstin) || "").trim().toUpperCase();

		if (!gstinValue) return null;
		if (!CONFIG.patterns.gstin.test(gstinValue)) return null;
		if (!isValidGstinChecksum(gstinValue)) return null;

		return gstinValue;
	}

	/**
	 * Reconciles the PAN field against the PAN embedded in an already-valid
	 * GSTIN: auto-fills PAN if it's empty, or warns (without overwriting) on
	 * a mismatch. Shared by both the GSTIN and PAN field handlers, and by
	 * submit-time validation, so all three call sites apply identical logic.
	 *
	 * @param {string} validatedGstin - A GSTIN that has already passed shape + checksum checks.
	 */
	function reconcilePanWithGstin(validatedGstin) {
		const extractedPan = extractPanFromGstin(validatedGstin);
		const currentPan = (frappe.web_form.get_value(CONFIG.fields.pan) || "").trim().toUpperCase();

		if (!currentPan) {
			setFieldValueSilently(CONFIG.fields.pan, extractedPan);
		} else if (currentPan !== extractedPan) {
			notify(CONFIG.messages.panMismatch(currentPan, extractedPan));
		}
	}

	/**
	 * Cleans and standardizes phone number inputs into E.164 international
	 * format. Strips spaces, parentheses, dots and hyphens, then treats any
	 * of the following as a domestic number and prepends
	 * "+" + CONFIG.defaultCountryCode:
	 *   - a bare 10-digit number                    (9876543210)
	 *   - a leading-zero domestic-dialing prefix     (09876543210)
	 *   - a bare (no "+") country code + 10 digits   (919876543210)
	 * Anything else (e.g. already-prefixed "+..." numbers, or numbers that
	 * don't match any of the above shapes) is returned as-is after stripping
	 * separators, and is left for CONFIG.patterns.mobile to accept or reject.
	 *
	 * @param {string} rawMobile - Raw user input.
	 * @returns {string} Cleaned phone number.
	 */
	function normalizeMobileNumber(rawMobile) {
		if (!rawMobile) return "";

		const cleaned = String(rawMobile).replace(/[\s\-().]/g, "");
		const countryCode = CONFIG.defaultCountryCode;

		if (new RegExp(`^0\\d{10}$`).test(cleaned)) {
			// Leading-zero domestic-dialing prefix, e.g. 0-9876543210
			return `+${countryCode}${cleaned.substring(1)}`;
		}

		if (new RegExp(`^${countryCode}\\d{10}$`).test(cleaned)) {
			// Bare country code with no "+", e.g. 919876543210
			return `+${cleaned}`;
		}

		if (/^\d{10}$/.test(cleaned)) {
			// Bare 10-digit subscriber number, e.g. 9876543210
			return `+${countryCode}${cleaned}`;
		}

		return cleaned;
	}

	/**
	 * Updates a web form field only when the new value differs from the
	 * current one, avoiding redundant writes. (Whether frappe.web_form's own
	 * "on" handlers re-fire on a programmatic set_value is a framework
	 * internal I don't have hard confirmation on either way for this
	 * version - this guard is harmless regardless: it's either preventing a
	 * real re-entrancy loop, or just skipping a no-op write.)
	 *
	 * @param {string} fieldname - Field identifier.
	 * @param {string} value - New value.
	 */
	function setFieldValueSilently(fieldname, value) {
		const currentValue = frappe.web_form.get_value(fieldname);
		if (currentValue !== value) {
			frappe.web_form.set_value(fieldname, value);
		}
	}

	/**
	 * Trims a raw field value and, if trimming reduces it to an empty
	 * string (i.e. the field held only whitespace), clears the field
	 * outright so it isn't left showing as "filled" while being treated as
	 * blank everywhere else in this script.
	 *
	 * @param {string} fieldname - Field identifier.
	 * @param {string} rawValue - The value as read from the field.
	 * @returns {string} The trimmed value ("" if it was whitespace-only).
	 */
	function trimOrClearField(fieldname, rawValue) {
		const trimmed = (rawValue || "").trim();

		if (!trimmed && rawValue) {
			setFieldValueSilently(fieldname, "");
		}

		return trimmed;
	}

	// =========================================================================
	// 4. CORE VALIDATION LOGIC
	// =========================================================================

	/**
	 * Validates GSTIN structure & checksum, then reconciles/auto-fills the PAN field.
	 *
	 * @param {string} gstinValue - The input GSTIN string.
	 * @param {boolean} [isSubmitting=false] - If true, displays blocking modals on error.
	 * @returns {boolean} True if valid or empty; false if invalid.
	 */
	function validateGstinAndSyncPan(gstinValue, isSubmitting = false) {
		const trimmedGstin = trimOrClearField(CONFIG.fields.gstin, gstinValue);
		if (!trimmedGstin) return true;

		const normalizedGstin = trimmedGstin.toUpperCase();
		setFieldValueSilently(CONFIG.fields.gstin, normalizedGstin);

		// 1. Regex shape check (includes valid state-code prefix)
		if (!CONFIG.patterns.gstin.test(normalizedGstin)) {
			notify(CONFIG.messages.gstinInvalidShape, { isBlocking: isSubmitting });
			return false;
		}

		// 2. Modulo-36 checksum verification
		if (!isValidGstinChecksum(normalizedGstin)) {
			notify(CONFIG.messages.gstinInvalidChecksum, { isBlocking: isSubmitting });
			return false;
		}

		// 3. PAN derivation & reconciliation
		reconcilePanWithGstin(normalizedGstin);

		return true;
	}

	// =========================================================================
	// 5. LIVE FIELD-LEVEL EVENT HANDLERS
	// =========================================================================

	// GSTIN field: validates checksum & reconciles PAN on blur/change
	frappe.web_form.on(CONFIG.fields.gstin, (field, value) => {
		if (!value) return;
		validateGstinAndSyncPan(value, false);
	});

	// PAN field: enforces uppercase, checks 10-character structure, and -
	// if a valid GSTIN is already present - re-checks it against the PAN
	// embedded in that GSTIN (fix #1: this direction was previously missed).
	frappe.web_form.on(CONFIG.fields.pan, (field, value) => {
		if (!value) return;

		const normalizedPan = trimOrClearField(CONFIG.fields.pan, value).toUpperCase();
		if (!normalizedPan) return;

		setFieldValueSilently(CONFIG.fields.pan, normalizedPan);

		if (!CONFIG.patterns.pan.test(normalizedPan)) {
			notify(CONFIG.messages.panInvalid);
			return;
		}

		const validatedGstin = getValidatedGstinOrNull();
		if (validatedGstin) {
			reconcilePanWithGstin(validatedGstin);
		}
	});

	// Mobile field: normalizes formatting and validates international shape
	frappe.web_form.on(CONFIG.fields.mobile, (field, value) => {
		if (!value) return;

		const trimmedMobile = trimOrClearField(CONFIG.fields.mobile, value);
		if (!trimmedMobile) return;

		const cleanedMobile = normalizeMobileNumber(trimmedMobile);
		setFieldValueSilently(CONFIG.fields.mobile, cleanedMobile);

		if (!CONFIG.patterns.mobile.test(cleanedMobile)) {
			notify(CONFIG.messages.mobileInvalid);
		}
	});

	// =========================================================================
	// 6. FORM SUBMISSION VALIDATION HOOK
	// =========================================================================

	/**
	 * Final barrier executed by Frappe prior to form submission.
	 * Re-validates all three fields independently of whether their
	 * field-level handlers ever fired (e.g. a field that was filled but
	 * never blurred), and re-runs GSTIN/PAN reconciliation one last time.
	 *
	 * @returns {boolean} True allows submission; false halts form submission.
	 */
	frappe.web_form.validate = () => {
		const gstin = trimOrClearField(CONFIG.fields.gstin, frappe.web_form.get_value(CONFIG.fields.gstin)).toUpperCase();
		const pan = trimOrClearField(CONFIG.fields.pan, frappe.web_form.get_value(CONFIG.fields.pan)).toUpperCase();
		const mobile = normalizeMobileNumber(trimOrClearField(CONFIG.fields.mobile, frappe.web_form.get_value(CONFIG.fields.mobile)));

		// Synchronize normalized values back to the document prior to saving
		if (gstin) setFieldValueSilently(CONFIG.fields.gstin, gstin);
		if (pan) setFieldValueSilently(CONFIG.fields.pan, pan);
		if (mobile) setFieldValueSilently(CONFIG.fields.mobile, mobile);

		// 1. Validate GSTIN (and reconcile PAN against it) if present
		if (gstin && !validateGstinAndSyncPan(gstin, true)) {
			return false;
		}

		// 2. Validate PAN format if present
		if (pan && !CONFIG.patterns.pan.test(pan)) {
			notify(CONFIG.messages.panInvalid, { isBlocking: true });
			return false;
		}

		// 3. Validate Mobile format if present
		if (mobile && !CONFIG.patterns.mobile.test(mobile)) {
			notify(CONFIG.messages.mobileInvalid, { isBlocking: true });
			return false;
		}

		return true;
	};
})();

frappe.web_form.after_load = () => {
    // Determine the requested ledger type from the Web Form.
    // For a Customer ledger, use "Customer"; for a Supplier ledger,
    // use "Supplier".
    const partyType = frappe.web_form.get_value("party_type");

    // Require a valid party type before requesting ledger data.
    if (!["Customer", "Supplier"].includes(partyType)) {
        frappe.msgprint(
            __("Please select Customer or Supplier.")
        );
        return;
    }

    // Fetch ledger data from the server.
    // The server verifies that the requested party belongs to the
    // currently logged-in portal user.
    frappe.call({
        method: "get_portal_ledger",
        args: {
            party_type: partyType
        },
        callback: function (r) {
            const data = r.message;

            // Stop if the server returned no ledger context.
            if (!data) {
                frappe.msgprint(
                    __("Unable to load your ledger.")
                );
                return;
            }

            // The server-resolved party is authoritative.
            // Do not use a client-supplied party value here.
            console.log("Ledger Party:", data.party);
            console.log("Party Type:", data.party_type);
            console.log("Entries:", data.entries);
        }
    });
};
